class CalendarUtil {
    let events: ArrayList<Event>

    public init() {
        this.events = ArrayList<Event>()
    }

    public func add_event(event: Event): Unit {
        this.events.append(event)
    }

    public func remove_event(event: Event): Unit {
        let index = this.events.indexOf(event)
        if (index >= 0) {
            this.events.remove(index)
        }
    }

    public func get_events(date: DateTime): ArrayList<Event> {
        let eventsOnDate = ArrayList<Event>()
        for (event in this.events) {
            if (event.date.year == date.year && event.date.month == date.month && event.date.day == date.day) {
                eventsOnDate.append(event)
            }
        }
        return eventsOnDate
    }

    public func is_available(start_time: DateTime, end_time: DateTime): Bool {
        for (event in this.events) {
            if (start_time < event.end_time && end_time > event.start_time) {
                return false
            }
        }
        return true
    }

    public func get_available_slots(date: DateTime): ArrayList<(DateTime, DateTime)> {
        let availableSlots = ArrayList<(DateTime, DateTime)>()
        var startTime = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.day, hour: 0, minute: 0)
        let endTime = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.day, hour: 23, minute: 59)

        while (startTime < endTime) {
            let slotEndTime = startTime.add(TimeDuration(minutes: 60))
            if (this.is_available(startTime, slotEndTime)) {
                availableSlots.append((startTime, slotEndTime))
            }
            startTime = startTime.add(TimeDuration(minutes: 60))
        }
        return availableSlots
    }

    public func get_upcoming_events(num_events: Int64): ArrayList<Event> {
        let now = DateTime.now()
        let upcomingEvents = ArrayList<Event>()
        for (event in this.events) {
            if (event.start_time >= now) {
                upcomingEvents.append(event)
                if (upcomingEvents.size == num_events) {
                    break
                }
            }
        }
        return upcomingEvents
    }
}

import std.collection.HashMap

class CamelCaseMap {
    let _data: HashMap<String, Any>

    public init() {
        _data = HashMap<String, Any>()
    }

    public func __getitem__(key: String): Any {
        return _data[_convert_key(key) as String] ?? ()
    }

    public func __setitem__(key: String, value: Any): Unit {
        _data[_convert_key(key) as String] = value
    }

    public func __delitem__(key: String): Unit {
        _data.remove(_convert_key(key) as String)
    }

    public func __len__(): Int64 {
        return _data.size
    }

    public func _convert_key(key: Any): Any {
        match (key) {
            case s: String => _to_camel_case(s)
            case _ => key
        }
    }

    public static func _to_camel_case(key: String): String {
        let parts = key.split('_')
        var result = parts[0]
        for (i in 1..parts.size) {
            let part = parts[i]
            if (part.isEmpty()) {
                continue
            }
            result += part[0].toUpperCase() + part[1...]
        }
        return result
    }
}

import std.collection.ArrayList

class ChandrasekharSieve {

    /*
    This is a class that uses the Chandrasekhar's Sieve method to find all prime numbers within the range
    */

    let n: Int64
    var primes: ArrayList<Int64> = ArrayList<Int64>()

    public init(n: Int64) {
        /*
        Initialize the ChandrasekharSieve class with the given limit.
        :param n: Int64, the upper limit for generating prime numbers
        */
        this.n = n
        this.primes = generate_primes()
    }

    public func generate_primes(): ArrayList<Int64> {
        /*
        Generate prime numbers up to the specified limit using the Chandrasekhar sieve algorithm.
        :return: ArrayList<Int64>, a list of prime numbers
        >>> cs = ChandrasekharSieve(20)
        >>> cs.generate_primes()
        [2, 3, 5, 7, 11, 13, 17, 19]

        */
        if (this.n < 2) {
            return ArrayList<Int64>()
        }

        let sieve = ArrayList<Bool>()
        sieve.resize((this.n + 1).toInt64(), true)
        sieve[0] = false
        sieve[1] = false

        var p: Int64 = 2
        while (p * p <= this.n) {
            if (sieve[p.toInt64()]) {
                var i: Int64 = p * p
                for (i in p * p..this.n + 1 : p) {
                    sieve[i.toInt64()] = false
                }
            }
            p += 1
        }

        let primes = ArrayList<Int64>()
        for (i in 2..this.n + 1) {
            if (sieve[i.toInt64()]) {
                primes.append(i)
            }
        }

        return primes
    }

    public func get_primes(): ArrayList<Int64> {
        /*
        Get the list of generated prime numbers.
        :return: ArrayList<Int64>, a list of prime numbers
        >>> cs = ChandrasekharSieve(20)
        >>> cs.get_primes()
        [2, 3, 5, 7, 11, 13, 17, 19]

        */
        return this.primes
    }
}

