class DataStatistics2 {

    /*
    This is a class for performing data statistics, supporting to get the sum, minimum, maximum, variance, standard deviation, and correlation of a given dataset.
    */

    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        /*
        Initialize Data List
        :param data:ArrayList<Float64>
        */
        this.data = data
    }

    public func get_sum(): Float64 {
        /*
        Calculate the sum of data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_sum()
        10.0
        */
        var sum: Float64 = 0.0
        for (x in this.data) {
            sum += x
        }
        return sum
    }

    public func get_min(): Float64 {
        /*
        Calculate the minimum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_min()
        1.0
        */
        var minVal: Float64 = this.data[0]
        for (x in this.data) {
            if (x < minVal) {
                minVal = x
            }
        }
        return minVal
    }

    public func get_max(): Float64 {
        /*
        Calculate the maximum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_max()
        4.0
        */
        var maxVal: Float64 = this.data[0]
        for (x in this.data) {
            if (x > maxVal) {
                maxVal = x
            }
        }
        return maxVal
    }

    public func get_variance(): Float64 {
        /*
        Calculate variance, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_variance()
        1.25
        */
        let n = this.data.size()
        let mean = this.get_sum() / Float64(n)
        var sumSquaredDeviations: Float64 = 0.0
        for (x in this.data) {
            let diff = x - mean
            sumSquaredDeviations += diff * diff
        }
        let variance = sumSquaredDeviations / Float64(n)
        return round(variance * 100.0) / 100.0
    }

    public func get_std_deviation(): Float64 {
        /*
        Calculate standard deviation, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_std_deviation()
        1.12
        */
        let variance = this.get_variance()
        let stdDev = sqrt(variance)
        return round(stdDev * 100.0) / 100.0
    }

    public func get_correlation(): Float64 {
        /*
        Calculate correlation
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_correlation()
        1.0
        */
        if (this.data.size() < 2) {
            return 0.0
        }
        let n = this.data.size()
        let mean = this.get_sum() / Float64(n)
        var sumX = 0.0
        var sumY = 0.0
        var sumXY = 0.0
        var sumX2 = 0.0
        var sumY2 = 0.0
        for (i in 0..n) {
            let x = Float64(i)
            let y = this.data[i]
            sumX += x
            sumY += y
            sumXY += x * y
            sumX2 += x * x
            sumY2 += y * y
        }
        let numerator = Float64(n) * sumXY - sumX * sumY
        let denominator = sqrt((Float64(n) * sumX2 - sumX * sumX) * (Float64(n) * sumY2 - sumY * sumY))
        if (abs(denominator) < 1e-10) {
            return 0.0
        }
        return numerator / denominator
    }
}

import std.collection.ArrayList
