class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n = data1.size()
        var sum1 = 0.0
        var sum2 = 0.0
        for (i in 0..n) {
            sum1 += data1[i]
            sum2 += data2[i]
        }
        let mean1 = sum1 / n
        let mean2 = sum2 / n

        var numerator = 0.0
        var var1 = 0.0
        var var2 = 0.0
        for (i in 0..n) {
            let d1 = data1[i] - mean1
            let d2 = data2[i] - mean2
            numerator += d1 * d2
            var1 += d1 * d1
            var2 += d2 * d2
        }
        let denominator = sqrt(var1) * sqrt(var2)
        return if (denominator != 0.0) { numerator / denominator } else { 0.0 }
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size()
        var sum = 0.0
        for (x in data) {
            sum += x
        }
        let mean = sum / n
        var variance = 0.0
        for (x in data) {
            variance += (x - mean) * (x - mean)
        }
        variance /= n
        let std_deviation = sqrt(variance)

        if (std_deviation == 0.0) {
            return 0.0
        }
        var skew = 0.0
        for (x in data) {
            skew += pow(x - mean, 3.0)
        }
        skew *= n / ((n - 1) * (n - 2) * pow(std_deviation, 3.0))
        return skew
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size()
        var sum = 0.0
        for (x in data) {
            sum += x
        }
        let mean = sum / n
        var variance = 0.0
        for (x in data) {
            variance += (x - mean) * (x - mean)
        }
        variance /= n
        let std_dev = sqrt(variance)

        if (std_dev == 0.0) {
            return nan
        }
        var fourth_moment = 0.0
        for (x in data) {
            fourth_moment += pow(x - mean, 4.0)
        }
        fourth_moment /= n
        let kurtosis_value = (fourth_moment / pow(std_dev, 4.0)) - 3.0
        return kurtosis_value
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let coefficient = 1.0 / (sigma * sqrt(2.0 * Pi))
        let result = ArrayList<Float64>()
        for (x in data) {
            let exponent = -0.5 * pow((x - mu) / sigma, 2.0)
            result.append(coefficient * exp(exponent))
        }
        return result
    }
}

import std.collection.ArrayList

class DecryptionUtils {

    /*
    This is a class that provides methods for decryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the decryption utility with a key.
        :param key: The key to use for decryption,String.
        */
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        /*
        Deciphers the given ciphertext using the Caesar cipher
        :param ciphertext: The ciphertext to decipher,String.
        :param shift: The shift to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.caesar_decipher('ifmmp', 1)
        'hello'

        */
        var plaintext = ""
        for (c in ciphertext) {
            if (c >= 'A' && c <= 'Z') {
                let offset = (c - 'A' - shift) % 26
                let newChar = if (offset >= 0) {
                    'A' + offset
                } else {
                    'Z' + offset + 1
                }
                plaintext += newChar
            } else if (c >= 'a' && c <= 'z') {
                let offset = (c - 'a' - shift) % 26
                let newChar = if (offset >= 0) {
                    'a' + offset
                } else {
                    'z' + offset + 1
                }
                plaintext += newChar
            } else {
                plaintext += c
            }
        }
        return plaintext
    }

    public func vigenere_decipher(ciphertext: String): String {
        /*
        Deciphers the given ciphertext using the Vigenere cipher
        :param ciphertext: The ciphertext to decipher,String.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.vigenere_decipher('ifmmp')
        'ybocl'

        */
        var decrypted_text = ""
        var key_index = 0
        for (char in ciphertext) {
            if (char >= 'A' && char <= 'Z') {
                let shift = (this.key[key_index % this.key.size].toLower() - 'a')
                let offset = (char - 'A' - shift) % 26
                let newChar = if (offset >= 0) {
                    'A' + offset
                } else {
                    'Z' + offset + 1
                }
                decrypted_text += newChar
                key_index += 1
            } else if (char >= 'a' && char <= 'z') {
                let shift = (this.key[key_index % this.key.size].toLower() - 'a')
                let offset = (char - 'a' - shift) % 26
                let newChar = if (offset >= 0) {
                    'a' + offset
                } else {
                    'z' + offset + 1
                }
                decrypted_text += newChar
                key_index += 1
            } else {
                decrypted_text += char
            }
        }
        return decrypted_text
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        /*
        Deciphers the given ciphertext using the Rail Fence cipher
        :param encrypted_text: The ciphertext to decipher,String.
        :param rails: The number of rails to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.rail_fence_decipher('Hoo!el,Wrdl l', 3)
        'Hello, World!'

        */
        let fence = ArrayList<ArrayList<Char>>()
        let len = encrypted_text.size
        for (i in 0..rails) {
            let row = ArrayList<Char>()
            for (j in 0..len) {
                row.append('\n')
            }
            fence.append(row)
        }

        var direction = -1
        var row = 0
        var col = 0

        for (i in 0..len) {
            if (row == 0 || row == rails - 1) {
                direction = -direction
            }
            fence[row].set(col, ' ')
            col += 1
            row += direction
        }

        var index = 0
        for (i in 0..rails) {
            for (j in 0..len) {
                if (fence[i][j] == ' ') {
                    fence[i].set(j, encrypted_text[index])
                    index += 1
                }
            }
        }

        var plain_text = ""
        direction = -1
        row = 0
        col = 0
        for (i in 0..len) {
            if (row == 0 || row == rails - 1) {
                direction = -direction
            }
            plain_text += fence[row][col]
            col += 1
            row += direction
        }

        return plain_text
    }
}

