class LongestWord {

    let word_list: ArrayList<String>

    public init() {
        this.word_list = ArrayList<String>()
    }

    public func add_word(word: String): Unit {
        this.word_list.append(word)
    }

    public func find_longest_word(sentence: String): String {
        var longest = ""
        let lower = sentence.toLowerCase()
        let re = Regex("[\\p{P}]")
        let noPunct = re.replaceAll(lower, "")
        let words = noPunct.split(" ")
        for (word in words) {
            if (this.word_list.contains(word) && word.size > longest.size) {
                longest = word
            }
        }
        return longest
    }
}

import std.collection.ArrayList
import std.collection.HashSet
import std.random.Random

class MahjongConnect {

    let BOARD_SIZE: ArrayList<Int64>
    let ICONS: ArrayList<String>
    var board: ArrayList<ArrayList<String>>

    public init(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>) {
        this.BOARD_SIZE = BOARD_SIZE
        this.ICONS = ICONS
        this.board = create_board(BOARD_SIZE, ICONS)
    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        let rand = Random()
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]
        let board = ArrayList<ArrayList<String>>()
        for (_ in 0..rows) {
            let row = ArrayList<String>()
            for (_ in 0..cols) {
                row.append(ICONS[rand.nextInt64(ICONS.size)])
            }
            board.append(row)
        }
        return board
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        if (!(0 <= x1 && x1 < BOARD_SIZE[0] && 0 <= y1 && y1 < BOARD_SIZE[1] &&
              0 <= x2 && x2 < BOARD_SIZE[0] && 0 <= y2 && y2 < BOARD_SIZE[1])) {
            return false
        }
        if (pos1 == pos2) {
            return false
        }
        if (board[x1][y1] != board[x2][y2]) {
            return false
        }
        return has_path(pos1, pos2)
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let visited = ArrayList<(Int64, Int64)>()
        let stack = ArrayList<(Int64, Int64)>()
        stack.append(pos1)
        let targetIcon = board[pos1.0][pos1.1]
        while (stack.size > 0) {
            let current = stack.removeAt(stack.size - 1)
            if (current == pos2) {
                return true
            }
            if (contains(visited, current)) {
                continue
            }
            visited.append(current)
            let (x, y) = current
            let directions = ArrayList<(Int64, Int64)>()
            directions.append((0, 1))
            directions.append((0, -1))
            directions.append((1, 0))
            directions.append((-1, 0))
            for (dir in directions) {
                let nx = x + dir.0
                let ny = y + dir.1
                if (0 <= nx && nx < BOARD_SIZE[0] && 0 <= ny && ny < BOARD_SIZE[1]) {
                    if (!contains(visited, (nx, ny)) && board[nx][ny] == targetIcon) {
                        stack.append((nx, ny))
                    }
                }
            }
        }
        return false
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>, pos: (Int64, Int64)): Bool {
        for (v in visited) {
            if (v == pos) {
                return true
            }
        }
        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        board[pos1.0][pos1.1] = " "
        board[pos2.0][pos2.1] = " "
    }

    public func is_game_over(): Bool {
        for (row in board) {
            for (cell in row) {
                if (cell != " ") {
                    return false
                }
            }
        }
        return true
    }
}

class Manacher {

    let input_string: String

    public init(input_string: String) {
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        if (center - diff == -1 || center + diff == string.size
                || string[center - diff] != string[center + diff]) {
            return 0
        }
        return 1 + palindromic_length(center, diff + 1, string)
    }

    public func palindromic_string(): String {
        var max_length: Int64 = 0
        var new_input_string = ""
        var output_string = ""

        for (i in 0..input_string.size - 1) {
            new_input_string += input_string[i] + "|"
        }
        new_input_string += input_string[input_string.size - 1]

        var start: Int64 = 0
        for (i in 0..new_input_string.size) {
            var length = palindromic_length(i, 1, new_input_string)
            if (max_length < length) {
                max_length = length
                start = i
            }
        }

        for (i in start - max_length..start + max_length) {
            let c = new_input_string[i]
            if (c != '|') {
                output_string += c
            }
        }

        return output_string
    }
}

import std.collection.ArrayList
import std.math.abs

class MetricsCalculator {

    var true_positives: Int64
    var false_positives: Int64
    var false_negatives: Int64
    var true_negatives: Int64

    public init() {
        this.true_positives = 0
        this.false_positives = 0
        this.false_negatives = 0
        this.true_negatives = 0
    }

    public func update(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Unit {
        let len = predicted_labels.size()
        for (i in 0..len) {
            let predicted = predicted_labels[i]
            let trueLabel = true_labels[i]
            if (predicted == 1 && trueLabel == 1) {
                this.true_positives += 1
            } else if (predicted == 1 && trueLabel == 0) {
                this.false_positives += 1
            } else if (predicted == 0 && trueLabel == 1) {
                this.false_negatives += 1
            } else {
                this.true_negatives += 1
            }
        }
    }

    public func precision(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        this.update(predicted_labels, true_labels)
        let denominator = this.true_positives + this.false_positives
        if (denominator == 0) {
            return 0.0
        }
        return this.true_positives.toFloat64() / denominator.toFloat64()
    }

    public func recall(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        this.update(predicted_labels, true_labels)
        let denominator = this.true_positives + this.false_negatives
        if (denominator == 0) {
            return 0.0
        }
        return this.true_positives.toFloat64() / denominator.toFloat64()
    }

    public func f1_score(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        this.update(predicted_labels, true_labels)
        let p = this.precision(predicted_labels, true_labels)
        let r = this.recall(predicted_labels, true_labels)
        let sum = p + r
        if (sum == 0.0) {
            return 0.0
        }
        return 2.0 * p * r / sum
    }

    public func accuracy(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        this.update(predicted_labels, true_labels)
        let total = this.true_positives + this.true_negatives + this.false_positives + this.false_negatives
        if (total == 0) {
            return 0.0
        }
        (this.true_positives + this.true_negatives).toFloat64() / total.toFloat64()
    }
}

