class MinesweeperGame {

    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        let rng = Random()
        let arr = ArrayList<ArrayList<Int64>>()
        for (i in 0..n) {
            let row = ArrayList<Int64>()
            for (j in 0..n) {
                row.append(0)
            }
            arr.append(row)
        }
        for (num in 0..k) {
            let x = rng.nextInt64(0, n-1)
            let y = rng.nextInt64(0, n-1)
            arr[y][x] = -1
            if (x >= 0 && x <= n-2) && (y >= 0 && y <= n-1) {
                if arr[y][x+1] != -1 {
                    arr[y][x+1] += 1
                }
            }
            if (x >= 1 && x <= n-1) && (y >= 0 && y <= n-1) {
                if arr[y][x-1] != -1 {
                    arr[y][x-1] += 1
                }
            }
            if (x >= 1 && x <= n-1) && (y >= 1 && y <= n-1) {
                if arr[y-1][x-1] != -1 {
                    arr[y-1][x-1] += 1
                }
            }
            if (x >= 0 && x <= n-2) && (y >= 1 && y <= n-1) {
                if arr[y-1][x+1] != -1 {
                    arr[y-1][x+1] += 1
                }
            }
            if (x >= 0 && x <= n-1) && (y >= 1 && y <= n-1) {
                if arr[y-1][x] != -1 {
                    arr[y-1][x] += 1
                }
            }
            if (x >= 0 && x <= n-2) && (y >= 0 && y <= n-2) {
                if arr[y+1][x+1] != -1 {
                    arr[y+1][x+1] += 1
                }
            }
            if (x >= 1 && x <= n-1) && (y >= 0 && y <= n-2) {
                if arr[y+1][x-1] != -1 {
                    arr[y+1][x-1] += 1
                }
            }
            if (x >= 0 && x <= n-1) && (y >= 0 && y <= n-2) {
                if arr[y+1][x] != -1 {
                    arr[y+1][x] += 1
                }
            }
        }
        let result = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            let row = ArrayList<String>()
            for (j in 0..n) {
                if arr[i][j] == -1 {
                    row.append("X")
                } else {
                    row.append(arr[i][j].toString())
                }
            }
            result.append(row)
        }
        return result
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        let result = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            let row = ArrayList<String>()
            for (j in 0..n) {
                row.append("-")
            }
            result.append(row)
        }
        return result
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for (i in 0..n) {
            for (j in 0..n) {
                if map[i][j] == "-" && minesweeper_map[i][j] != "X" {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        if minesweeper_map[x][y] == "X" {
            return false
        } else {
            player_map[x][y] = minesweeper_map[x][y]
            score += 1
            if check_won(player_map) {
                return true
            }
            return player_map
        }
    }
}

