import std.string.*

class NumberWordFormatter {
    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN", "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        match (x) {
            case Some(s) => return format_string(s)
            case None => return ""
        }
    }

    public func format_string(x: String): String {
        let parts = x.split(".", 2)
        let lstr = parts[0]
        let rstr = parts.size() > 1 ? parts[1] : ""
        var lstrrev = lstr.reversed()
        var a = Array<String>(["", "", "", "", ""])

        if (lstrrev.size() % 3 == 1) {
            lstrrev += "00"
        } else if (lstrrev.size() % 3 == 2) {
            lstrrev += "0"
        }

        var lm = ""
        let n = lstrrev.size() / 3
        for (i in 0..n) {
            let chunk = lstrrev[i*3..i*3+3].reversed()
            a[i] = chunk
            if (chunk != "000") {
                lm = trans_three(chunk) + " " + parse_more(i) + " " + lm
            }
        }

        let xs = rstr.size() > 0 ? "AND CENTS " + trans_two(rstr) + " " : ""
        if (lm.trim().isEmpty()) {
            return "ZERO ONLY"
        } else {
            return "${lm.trim()} ${xs}ONLY"
        }
    }

    public func trans_two(s: String): String {
        let padded = s.padEnd(2, '0')
        if (padded[0] == '0') {
            return NUMBER[Int64.parse(padded[1])]
        } else if (padded[0] == '1') {
            return NUMBER_TEEN[Int64.parse(padded) - 10]
        } else if (padded[1] == '0') {
            return NUMBER_TEN[Int64.parse(padded[0]) - 1]
        } else {
            return NUMBER_TEN[Int64.parse(padded[0]) - 1] + " " + NUMBER[Int64.parse(padded[1])]
        }
    }

    public func trans_three(s: String): String {
        if (s[0] == '0') {
            return trans_two(s[1..])
        } else if (s[1..] == "00") {
            return "${NUMBER[Int64.parse(s[0])]} HUNDRED"
        } else {
            return "${NUMBER[Int64.parse(s[0])]} HUNDRED AND ${trans_two(s[1..])}"
        }
    }

    public func parse_more(i: Int64): String {
        return NUMBER_MORE[i]
    }
}

class NumericEntityUnescaper {

    public init() {}

    public func replace(string: String): String {
        let out = StringBuilder()
        var pos = 0
        let length = string.length
        while (pos < length - 2) {
            if (string[pos] == '&' && string[pos + 1] == '#') {
                var start = pos + 2
                var isHex = false
                let firstChar = string[start]
                if (firstChar == 'x' || firstChar == 'X') {
                    start += 1
                    isHex = true
                }
                if (start == length) {
                    return out.toString()
                }
                var end = start
                while (end < length && NumericEntityUnescaper.is_hex_char(string[end])) {
                    end += 1
                }
                if (end < length && string[end] == ';') {
                    let entityStr = string[start..end]
                    let entityValue = if (isHex) {
                        Int64.parse(entityStr, 16).getOrThrow()
                    } else {
                        Int64.parse(entityStr, 10).getOrThrow()
                    }
                    if (entityValue >= 0 && entityValue <= 0x10FFFF) {
                        out.append(Rune(entityValue))
                    }
                    pos = end + 1
                    continue
                }
            }
            out.append(string[pos])
            pos += 1
        }
        return out.toString()
    }

    public static func is_hex_char(char: Rune): Bool {
        return char >= '0' && char <= '9' || char >= 'a' && char <= 'f' || char >= 'A' && char <= 'F'
    }
}

