import std.collection.HashMap
import std.collection.ArrayList

class SignInSystem {

    /*
    This is a class as sigin in system, including adding users, signing in/out, checking sign-in status, and retrieving signed-in/not signed-in users.
    */

    let users: HashMap<String, Bool>

    public init() {
        /*
        Initialize the sign-in system.
        */
        users = HashMap<String, Bool>()
    }

    public func add_user(username: String): Bool {
        /*
        Add a user to the sign-in system if the user wasn't in the this.users.
        And the initial state is false.
        :param username: String, the username to be added.
        :return: Bool, true if the user is added successfully, false if the user already exists.
        >>> signInSystem.add_user("mike")
        true
        >>> signInSystem.add_user("mike")
        false
        */
        if (users.contains(username)) {
            return false
        } else {
            users[username] = false
            return true
        }
    }

    public func sign_in(username: String): Bool {
        /*
        Sign in a user if the user was in the this.users and change the state to true.
        :param username: String, the username to be signed in.
        :return: Bool, true if the user is signed in successfully, false if the user does not exist.
        >>> signInSystem.sign_in("mike")
        true
        >>> signInSystem.sign_in("mik")
        false
        */
        if (!users.contains(username)) {
            return false
        } else {
            users[username] = true
            return true
        }
    }

    public func check_sign_in(username: String): Bool {
        /*
        Check if a user is signed in.
        :param username: String, the username to be checked.
        :return: Bool, true if the user is signed in, false if the user does not exist or is not signed in.
        >>> signInSystem.check_sign_in("jack")
        false
        >>> signInSystem.add_user("jack")
        >>> signInSystem.check_sign_in("jack")
        >>> signInSystem.sign_in("jack")
        >>> signInSystem.check_sign_in("jack")
        true
        */
        if (!users.contains(username)) {
            return false
        } else {
            return users[username]
        }
    }

    public func all_signed_in(): Bool {
        /*
        Check if all users are signed in.
        :return: Bool, true if all users are signed in, false otherwise.
        >>> signInSystem.add_user("jack")
        true
        >>> signInSystem.sign_in("jack")
        >>> signInSystem.all_signed_in()
        true
        */
        if (users.size() == 0) {
            return true
        }
        for ((_, v) in users) {
            if (!v) {
                return false
            }
        }
        return true
    }

    public func all_not_signed_in(): ArrayList<String> {
        /*
        Get a list of usernames that are not signed in.
        :return: ArrayList<String>, a list of usernames that are not signed in.
        >>> signInSystem = SignInSystem()
        >>> signInSystem.add_user("a")
        true
        >>> signInSystem.add_user("b")
        true
        >>> signInSystem.all_not_signed_in()
        ['a', 'b']
        */
        let res = ArrayList<String>()
        for ((k, v) in users) {
            if (!v) {
                res.append(k)
            }
        }
        return res
    }
}

import std.collection.ArrayList
import std.random.Random

class Snake {

    /*
    The class is a snake game, with allows snake to move and eat food, and also enables to reset, and generat a random food position.
    */

    var length: Int64
    let SCREEN_WIDTH: Int64
    let SCREEN_HEIGHT: Int64
    let BLOCK_SIZE: Int64
    var positions: ArrayList<ArrayList<Int64>>
    var score: Int64
    var food_position: ArrayList<Int64>

    public init(SCREEN_WIDTH: Int64, SCREEN_HEIGHT: Int64, BLOCK_SIZE: Int64, food_position: ArrayList<Int64>) {
        /*
        Initialize the length of the snake, screen width, screen height, block size, snake head position, score, and food position.
        :param SCREEN_WIDTH: Int64
        :param SCREEN_HEIGHT: Int64
        :param BLOCK_SIZE: Int64, Size of moving units
        :param food_position: ArrayList<Int64>, representing the position(x, y) of food.
        */
        this.length = 1
        this.SCREEN_WIDTH = SCREEN_WIDTH
        this.SCREEN_HEIGHT = SCREEN_HEIGHT
        this.BLOCK_SIZE = BLOCK_SIZE
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([SCREEN_WIDTH / 2, SCREEN_HEIGHT / 2])])
        this.score = 0
        this.food_position = food_position
    }

    public func move(direction: ArrayList<Int64>): Unit {
        /*
        Move the snake in the specified direction. If the new position of the snake's head is equal to the position of the food, then eat the food; If the position of the snake's head is equal to the position of its body, then start over, otherwise its own length plus one.
        :param direction: ArrayList<Int64>, representing the direction of movement (x, y).
        :return: Unit
        >>> snake.move(ArrayList<Int64>([1,1]))
        this.length = 1
        this.positions = [(51, 51), (50, 50)]
        this.score = 10
        */
        let cur = this.positions[0]
        let x = direction[0]
        let y = direction[1]

        let newX = ((cur[0] + x * this.BLOCK_SIZE) % this.SCREEN_WIDTH + this.SCREEN_WIDTH) % this.SCREEN_WIDTH
        let newY = ((cur[1] + y * this.BLOCK_SIZE) % this.SCREEN_HEIGHT + this.SCREEN_HEIGHT) % this.SCREEN_HEIGHT
        let newPos = ArrayList<Int64>([newX, newY])

        if (newPos[0] == this.food_position[0] && newPos[1] == this.food_position[1]) {
            this.eat_food()
        }

        var collision = false
        if (this.positions.size() > 2) {
            for (i in 2..this.positions.size()) {
                if (newPos[0] == this.positions[i][0] && newPos[1] == this.positions[i][1]) {
                    collision = true
                    break
                }
            }
        }
        if (collision) {
            this.reset()
        } else {
            this.positions.insert(0, newPos)
            if (this.positions.size() > this.length) {
                this.positions.pop()
            }
        }
    }

    public func random_food_position(): Unit {
        /*
        Randomly generate a new food position, but don't place it on the snake.
        :return: Unit, Change the food position
        */
        let rand = Random()
        let cols = this.SCREEN_WIDTH / this.BLOCK_SIZE
        let rows = this.SCREEN_HEIGHT / this.BLOCK_SIZE
        var newFood: ArrayList<Int64>
        while (true) {
            newFood = ArrayList<Int64>([
                rand.nextInt64(0, cols - 1) * this.BLOCK_SIZE,
                rand.nextInt64(0, rows - 1) * this.BLOCK_SIZE
            ])
            var onSnake = false
            for (pos in this.positions) {
                if (newFood[0] == pos[0] && newFood[1] == pos[1]) {
                    onSnake = true
                    break
                }
            }
            if (!onSnake) {
                break
            }
        }
        this.food_position = newFood
    }

    public func reset(): Unit {
        /*
        Reset the snake to its initial state. Set the length to 1, the snake head position to ((SCREEN_WIDTH/2), (SCREEN_HEIGHT/2)), the score to 0, and randomly generate new food position.
        :return: Unit
        >>> snake = Snake(100, 100, 1, ArrayList<Int64>([51, 51]))
        >>> snake.reset()
        this.length = 1
        this.positions = [(50, 50)]
        this.score = 0
        this.random_food_position()
        */
        this.length = 1
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([this.SCREEN_WIDTH / 2, this.SCREEN_HEIGHT / 2])])
        this.score = 0
        this.random_food_position()
    }

    public func eat_food(): Unit {
        /*
        Increase the length of the snake by 1 and increase the score by 100. Randomly generate a new food position, but
        don't place it on the snake.
        :return: Unit
        >>> snake = Snake(100, 100, 1, ArrayList<Int64>([51, 51]))
        >>> snake.move(ArrayList<Int64>([1,1]))
        >>> snake.eat_food()
        this.length = 2
        this.score = 10
        */
        this.length += 1
        this.score += 100
        this.random_food_position()
    }
}

import std.collection.ArrayList
import std.regex.Regex
import std.unicode.UnicodeStringExtension

class SplitSentence {

    public func split_sentences(sentences_string: String): ArrayList<String> {
        let pattern = r"(?<!\w\.\w.)(?<![A-Z][a-z]\.)(?<=\.|\?)\s"
        let re = Regex(pattern)
        let parts = re.split(sentences_string)
        let result = ArrayList<String>()
        for (part in parts) {
            result.append(part)
        }
        return result
    }

    public func count_words(sentence: String): Int64 {
        let cleaned = Regex("[^a-zA-Z\\s]").replaceAll(sentence, "")
        let words = cleaned.split(Regex("\\s+"))
        var count = 0
        for (word in words) {
            if (word.size > 0) {
                count++
            }
        }
        return count
    }

    public func process_text_file(sentences_string: String): Int64 {
        let sentences = split_sentences(sentences_string)
        var max_count = 0
        for (sentence in sentences) {
            let count = count_words(sentence)
            if (count > max_count) {
                max_count = count
            }
        }
        return max_count
    }
}

import std.collection.ArrayList
import std.collection.HashMap

class SQLGenerator {

    let table_name: String

    public init(table_name: String) {
        this.table_name = table_name
    }

    public func select(fields!: Option<ArrayList<String>> = None, condition!: Option<String> = None): String {
        var fields_str: String
        if (fields == None) {
            fields_str = "*"
        } else {
            fields_str = fields.get().join(", ")
        }
        var sql = "SELECT ${fields_str} FROM ${this.table_name}"
        if (condition != None) {
            sql += " WHERE ${condition.get()}"
        }
        return sql + ";"
    }

    public func insert(data: HashMap<String, String>): String {
        let keys = data.keys()
        let fields = keys.join(", ")
        let values_arr = keys.map({ k => "'${data[k]}'" })
        let values = values_arr.join(", ")
        return "INSERT INTO ${this.table_name} (${fields}) VALUES (${values});"
    }

    public func update(data: HashMap<String, String>, condition: String): String {
        let pairs = data.keys().map({ k => "${k} = '${data[k]}'" })
        let set_clause = pairs.join(", ")
        return "UPDATE ${this.table_name} SET ${set_clause} WHERE ${condition};"
    }

    public func delete(condition: String): String {
        return "DELETE FROM ${this.table_name} WHERE ${condition};"
    }

    public func select_female_under_age(age: Int64): String {
        let cond = "age < ${age} AND gender = 'female'"
        return this.select(condition: cond)
    }

    public func select_by_age_range(min_age: Int64, max_age: Int64): String {
        let cond = "age BETWEEN ${min_age} AND ${max_age}"
        return this.select(condition: cond)
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class SQLQueryBuilder {

    /*
    This class provides to build SQL queries, including SELECT, INSERT, UPDATE, and DELETE statements. 
    */

    public static func select(table: String, columns!: ArrayList<String> = ArrayList<String>(['*']), where_condition!: Option<HashMap<String, String>> = None): String {
        /*
        Generate the SELECT SQL statement from the given parameters.
        :param table: String, the query table in database.
        :param columns: ArrayList of String, ['col1', 'col2'].
        :param where_condition: Option<HashMap<String, String>>, {key1: value1, key2: value2 ...}. The query condition.
        return query: String, the SQL query statement.
        >>> SQLQueryBuilder.select('table1', columns: ArrayList<String>(["col1","col2"]), where_condition: HashMap<String,String>([("age", "15")]))
        "SELECT col1, col2 FROM table1 WHERE age='15'"
        */
        var cols = ""
        if (columns.size() == 1 && columns[0] == "*") {
            cols = "*"
        } else {
            cols = columns.join(", ")
        }
        var query = "SELECT " + cols + " FROM " + table
        if (where_condition != None) {
            var conds = ArrayList<String>()
            for ((k, v) in where_condition.get()) {
                conds.append(k + "='" + v + "'")
            }
            query += " WHERE " + conds.join(" AND ")
        }
        return query
    }

    public static func insert(table: String, data: HashMap<String, String>): String {
        /*
        Generate the INSERT SQL statement from the given parameters.
        :param table: String, the table to be inserted in database.
        :param data: HashMap<String, String>, the key and value in SQL insert statement
        :return query: String, the SQL insert statement.
        >>> SQLQueryBuilder.insert('table1', HashMap<String,String>([("name", "Test"), ("age", "14")]))
        "INSERT INTO table1 (name, age) VALUES ('Test', '14')"
        */
        var keys = ArrayList<String>()
        var values = ArrayList<String>()
        for ((k, v) in data) {
            keys.append(k)
            values.append("'" + v + "'")
        }
        return "INSERT INTO " + table + " (" + keys.join(", ") + ") VALUES (" + values.join(", ") + ")"
    }

    public static func delete(table: String, where_condition!: Option<HashMap<String, String>> = None): String {
        /*
        Generate the DELETE SQL statement from the given parameters.
        :param table: String, the table that will be excuted with DELETE operation in database
        :param where_condition: Option<HashMap<String, String>>, {key1: value1, key2: value2 ...}. The query condition.
        :return query: String, the SQL delete statement.
        >>> SQLQueryBuilder.delete('table1', where_condition: HashMap<String,String>([("name", "Test"), ("age", "14")]))
        "DELETE FROM table1 WHERE name='Test' AND age='14'"
        */
        var query = "DELETE FROM " + table
        if (where_condition != None) {
            var conds = ArrayList<String>()
            for ((k, v) in where_condition.get()) {
                conds.append(k + "='" + v + "'")
            }
            query += " WHERE " + conds.join(" AND ")
        }
        return query
    }

    public static func update(table: String, data: HashMap<String, String>, where_condition!: Option<HashMap<String, String>> = None): String {
        /*
        Generate the UPDATE SQL statement from the given parameters.
        :param table: String, the table that will be excuted with UPDATE operation in database
        :param data: HashMap<String, String>, the key and value in SQL update statement
        :param where_condition: Option<HashMap<String, String>>, {key1: value1, key2: value2 ...}. The query condition.
        :return query: String, the SQL update statement.
        >>> SQLQueryBuilder.update('table1', HashMap<String,String>([("name", "Test2"), ("age", "15")]), where_condition: HashMap<String,String>([("name", "Test")]))
        "UPDATE table1 SET name='Test2', age='15' WHERE name='Test'"
        */
        var setParts = ArrayList<String>()
        for ((k, v) in data) {
            setParts.append(k + "='" + v + "'")
        }
        var query = "UPDATE " + table + " SET " + setParts.join(", ")
        if (where_condition != None) {
            var conds = ArrayList<String>()
            for ((k, v) in where_condition.get()) {
                conds.append(k + "='" + v + "'")
            }
            query += " WHERE " + conds.join(" AND ")
        }
        return query
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        if (data.size() == 0) {
            return 0.0
        }
        let sorted = ArrayList<Int64>()
        sorted.appendAll(data)
        sort(sorted, (a: Int64, b: Int64) => a < b)
        let n = sorted.size()
        if (n % 2 == 1) {
            return Float64(sorted[n / 2])
        } else {
            return (Float64(sorted[n / 2 - 1]) + Float64(sorted[n / 2])) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let counts = HashMap<Int64, Int64>()
        for (value in data) {
            counts[value] = counts.getOrDefault(value, 0) + 1
        }
        var maxCount = 0
        for (count in counts.values()) {
            if (count > maxCount) {
                maxCount = count
            }
        }
        let modeValues = ArrayList<Int64>()
        for (entry in counts.entries()) {
            if (entry.value == maxCount) {
                modeValues.append(entry.key)
            }
        }
        return modeValues
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if (x.size() != y.size() || x.size() == 0) {
            return None
        }
        let n = x.size()
        var sumX = 0
        var sumY = 0
        for (i in 0..n) {
            sumX += x[i]
            sumY += y[i]
        }
        let meanX = Float64(sumX) / Float64(n)
        let meanY = Float64(sumY) / Float64(n)
        var num = 0.0
        var denX = 0.0
        var denY = 0.0
        for (i in 0..n) {
            let dx = Float64(x[i]) - meanX
            let dy = Float64(y[i]) - meanY
            num += dx * dy
            denX += dx * dx
            denY += dy * dy
        }
        let den = sqrt(denX * denY)
        if (den == 0.0) {
            return None
        }
        return Some(num / den)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.size() == 0) {
            return None
        }
        var sum = 0
        for (value in data) {
            sum += value
        }
        return Some(Float64(sum) / Float64(data.size()))
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let matrix = ArrayList<ArrayList<Float64>>()
        if (data.size() == 0) {
            return matrix
        }
        let cols = data[0].size()
        for (i in 0..cols) {
            let row = ArrayList<Float64>()
            for (j in 0..cols) {
                let col1 = ArrayList<Int64>()
                let col2 = ArrayList<Int64>()
                for (k in 0..data.size()) {
                    col1.append(data[k][i])
                    col2.append(data[k][j])
                }
                let corr = correlation(col1, col2)
                match (corr) {
                    case Some(v) => row.append(v)
                    case None => row.append(0.0)
                }
            }
            matrix.append(row)
        }
        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        if (data.size() < 2) {
            return None
        }
        let m = mean(data)
        match (m) {
            case None => return None
            case Some(meanValue) =>
                var sum = 0.0
                for (x in data) {
                    let d = Float64(x) - meanValue
                    sum += d * d
                }
                let variance = sum / Float64(data.size() - 1)
                return Some(sqrt(variance))
        }
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let m = mean(data)
        let s = standard_deviation(data)
        match (m, s) {
            case (Some(meanValue), Some(stdDev)) =>
                if (stdDev == 0.0) {
                    return None
                }
                let z = ArrayList<Float64>()
                for (x in data) {
                    z.append((Float64(x) - meanValue) / stdDev)
                }
                return Some(z)
            case _ => return None
        }
    }
}

public func add_stock(stock: Stock): Unit {
        for (i in 0..this.portfolio.size) {
            let pf = this.portfolio[i]
            if (pf.name == stock.name) {
                pf.quantity += stock.quantity
                return
            }
        }
        this.portfolio.append(Stock(stock.name, stock.price, stock.quantity))
    }

    public func remove_stock(stock: Stock): Bool {
        for (i in 0..this.portfolio.size) {
            let pf = this.portfolio[i]
            if (pf.name == stock.name && pf.quantity >= stock.quantity) {
                pf.quantity -= stock.quantity
                if (pf.quantity == 0) {
                    this.portfolio.remove(i)
                }
                return true
            }
        }
        return false
    }

    public func buy_stock(stock: Stock): Bool {
        let cost = stock.price * Float64(stock.quantity)
        if (cost > this.cash_balance) {
            return false
        }
        this.add_stock(stock)
        this.cash_balance -= cost
        return true
    }

    public func sell_stock(stock: Stock): Bool {
        if (!this.remove_stock(stock)) {
            return false
        }
        this.cash_balance += stock.price * Float64(stock.quantity)
        return true
    }

    public func calculate_portfolio_value(): Float64 {
        var total = this.cash_balance
        for (s in this.portfolio) {
            total += s.price * Float64(s.quantity)
        }
        return total
    }

    public func get_portfolio_summary(): (Float64, ArrayList<HashMap<String, Any>>) {
        let summary = ArrayList<HashMap<String, Any>>()
        for (s in this.portfolio) {
            let entry = HashMap<String, Any>()
            entry["name"] = s.name
            entry["value"] = s.price * Float64(s.quantity)
            summary.append(entry)
        }
        return (this.calculate_portfolio_value(), summary)
    }

    public func get_stock_value(stock: Stock): Float64 {
        return stock.price * Float64(stock.quantity)
    }

import std.math.abs

class Thermostat {

    var current_temperature: Float64
    var target_temperature: Float64
    var mode: String

    public init(current_temperature: Float64, target_temperature: Float64, mode: String) {
        this.current_temperature = current_temperature
        this.target_temperature = target_temperature
        this.mode = mode
    }

    public func get_target_temperature(): Float64 {
        return this.target_temperature
    }

    public func set_target_temperature(temperature: Float64): Unit {
        this.target_temperature = temperature
    }

    public func get_mode(): String {
        return this.mode
    }

    public func set_mode(mode: String): Bool {
        if (mode == "heat" || mode == "cool") {
            this.mode = mode
            return true
        }
        return false
    }

    public func auto_set_mode(): Unit {
        if (this.current_temperature < this.target_temperature) {
            this.mode = "heat"
        } else {
            this.mode = "cool"
        }
    }

    public func auto_check_conflict(): Bool {
        if (this.current_temperature > this.target_temperature) {
            if (this.mode == "cool") {
                return true
            } else {
                this.auto_set_mode()
                return false
            }
        } else {
            if (this.mode == "heat") {
                return true
            } else {
                this.auto_set_mode()
                return false
            }
        }
    }

    public func simulate_operation(): Int64 {
        this.auto_set_mode()
        var use_time: Int64 = 0
        if (this.mode == "heat") {
            while (this.current_temperature < this.target_temperature) {
                this.current_temperature += 1.0
                use_time += 1
            }
        } else {
            while (this.current_temperature > this.target_temperature) {
                this.current_temperature -= 1.0
                use_time += 1
            }
        }
        return use_time
    }
}

import std.collection.ArrayList

class TicTacToe {

    /*
    The class represents a game of Tic-Tac-Toe and its functions include making a move on the board, checking for a winner, and determining if the board is full.
    */

    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(N!: Int64 = 3) {
        /*
        Initialize a 3x3 game board with all empty spaces and current symble player, default is 'X'.
        */
        this.board = ArrayList<ArrayList<String>>()
        for (_ in 0..3) {
            let row = ArrayList<String>()
            for (_ in 0..N) {
                row.add(' ')
            }
            this.board.add(row)
        }
        this.current_player = 'X'
    }

    public func make_move(row: Int64, col: Int64): Bool {
        /*
        Place the current player's mark at the specified position on the board and switch the mark.
        :param row: Int64, the row index of the position
        :param col: Int64, the column index of the position
        :return: Bool, indicating whether the move was successful or not
        >>> ttt.current_player
        'X'
        >>> ttt.make_move(1, 1)
        >>> ttt.current_player
        'O'
        */
        if (this.board[row][col] == ' ') {
            this.board[row][col] = this.current_player
            this.current_player = if (this.current_player == 'X') 'O' else 'X'
            return true
        } else {
            return false
        }
    }

    public func check_winner(): Option<String> {
        /*
        Check if there is a winner on the board in rows, columns and diagonals three directions
        :return: Option<String>, the mark of the winner ('X' or 'O'), or None if there is no winner yet
        >>> moves = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([1, 0]), ArrayList<Int64>([2, 0]), ArrayList<Int64>([1, 1]), ArrayList<Int64>([2, 1]), ArrayList<Int64>([1, 2])])
        >>> for move in moves:
        ...     ttt.make_move(move[0], move[1])
        >>> ttt.check_winner()
        'X'
        */
        for (row in this.board) {
            if (row[0] == row[1] && row[1] == row[2] && row[0] != ' ') {
                return Some(row[0])
            }
        }
        for (col in 0..3) {
            if (this.board[0][col] == this.board[1][col] && this.board[1][col] == this.board[2][col] && this.board[0][col] != ' ') {
                return Some(this.board[0][col])
            }
        }
        if (this.board[0][0] == this.board[1][1] && this.board[1][1] == this.board[2][2] && this.board[0][0] != ' ') {
            return Some(this.board[0][0])
        }
        if (this.board[0][2] == this.board[1][1] && this.board[1][1] == this.board[2][0] && this.board[0][2] != ' ') {
            return Some(this.board[0][2])
        }
        return None
    }

    public func is_board_full(): Bool {
        /*
        Check if the game board is completely filled.
        :return: Bool, indicating whether the game board is full or not
        >>> ttt.is_board_full()
        false
        */
        for (row in this.board) {
            for (cell in row) {
                if (cell == ' ') {
                    return false
                }
            }
        }
        return true
    }
}

