class VectorUtil {

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        let u1 = unitvec(vector_1)
        let u2 = unitvec(vector_2)
        return dot(u1, u2)
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let norm = normVec(vector_1)
        let result = ArrayList<Float64>()
        for (v in vectors_all) {
            let n = normVec(v)
            let d = dot(v, vector_1)
            if (abs(norm * n) < 1e-12) {
                result.append(0.0)
            } else {
                result.append(d / (norm * n))
            }
        }
        return result
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        if (vector_list_1.size() == 0 || vector_list_2.size() == 0) {
            throw ZeroDivisionError("At least one of the passed list is empty.")
        }
        let mean1 = unitvec(meanVec(vector_list_1))
        let mean2 = unitvec(meanVec(vector_list_2))
        return dot(mean1, mean2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let result = HashMap<String, Float64>()
        for (pair in number_dict) {
            let count = pair.1
            let w = log((Float64(totalNum + 1)) / (count + 1.0))
            result[pair.0] = w
        }
        return result
    }

    private static func dot(v1: ArrayList<Float64>, v2: ArrayList<Float64>): Float64 {
        var sum = 0.0
        for (i in 0..v1.size()) {
            sum += v1[i] * v2[i]
        }
        return sum
    }

    private static func normVec(v: ArrayList<Float64>): Float64 {
        var sum = 0.0
        for (x in v) {
            sum += x * x
        }
        return sqrt(sum)
    }

    private static func unitvec(v: ArrayList<Float64>): ArrayList<Float64> {
        let n = normVec(v)
        let res = ArrayList<Float64>()
        if (abs(n) < 1e-12) {
            for (x in v) {
                res.append(0.0)
            }
        } else {
            for (x in v) {
                res.append(x / n)
            }
        }
        return res
    }

    private static func meanVec(vecs: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        if (vecs.size() == 0) {
            return ArrayList<Float64>()
        }
        let dim = vecs[0].size()
        let mean = ArrayList<Float64>()
        for (i in 0..dim) {
            mean.append(0.0)
        }
        for (v in vecs) {
            for (i in 0..dim) {
                mean[i] += v[i]
            }
        }
        for (i in 0..dim) {
            mean[i] /= Float64(vecs.size())
        }
        return mean
    }
}

