                    power = power * 10
                }
                this.numwords[this.scales[idx]] = (power, 0)
            }
        }

        this.ordinal_words = HashMap<String, Int64>([("first", 1), ("second", 2), ("third", 3), ("fifth", 5), ("eighth", 8), ("ninth", 9), ("twelfth", 12)])
        this.ordinal_endings = ArrayList<(String, String)>([("ieth", "y"), ("th", "")])
    }

    public func text2int(textnum: String): String {
        let text = textnum.replace("-", " ")
        var current: Int64 = 0
        var result: Int64 = 0
        var curstring = ""
        var onnumber = false
        let words = text.split(" ")

        for (word in words) {
            var w = word
            if (this.ordinal_words.contains(w)) {
                let scale = 1
                let increment = this.ordinal_words[w]
                current = current * scale + increment
                onnumber = true
            } else {
                for (ending in this.ordinal_endings) {
                    let (suf, repl) = ending
                    if (w.endswith(suf)) {
                        w = w[0..(w.size - suf.size)] + repl
                        break
                    }
                }
                if (!this.numwords.contains(w)) {
                    if (onnumber) {
                        curstring += Int64ToString(result + current) + " "
                    }
                    curstring += word + " "
                    result = 0
                    current = 0
                    onnumber = false
                } else {
                    let (scale, increment) = this.numwords[w]
                    current = current * scale + increment
                    if (scale > 100) {
                        result += current
                        current = 0
                    }
                    onnumber = true
                }
            }
        }
        if (onnumber) {
            curstring += Int64ToString(result + current)
        }
        return curstring
    }

    public func is_valid_input(textnum: String): Bool {
        let text = textnum.replace("-", " ")
        let words = text.split(" ")
        for (word in words) {
            var w = word
            if (this.ordinal_words.contains(w)) {
                continue
            }
            for (ending in this.ordinal_endings) {
                let (suf, repl) = ending
                if (w.endswith(suf)) {
                    w = w[0..(w.size - suf.size)] + repl
                    break
                }
            }
            if (!this.numwords.contains(w)) {
                return false
            }
        }
        return true
    }
}
